<?php

/**
 * PHPCoord.
 *
 * @author Doug Wright
 */
declare(strict_types=1);

namespace PHPCoord\Geometry;

use PHPCoord\UnitOfMeasure\Angle\Degree;
use RuntimeException;

use function file_get_contents;
use function implode;
use function json_decode;

use const JSON_THROW_ON_ERROR;

/**
 * Precomputed OGC PointOnSurface for each EPSG extent, generated by EPSGImporter via Spatialite ST_PointOnSurface.
 *
 * @internal
 */
final class ExtentInteriorPoints
{
    /**
     * @var array<string, array{0: float, 1: float}>|null
     */
    private static ?array $points = null;

    /**
     * @param  string[]                    $extentCodes
     * @return array{0: Degree, 1: Degree}
     */
    public static function get(array $extentCodes): array
    {
        if (self::$points === null) {
            /** @var array<string, array{0: float, 1: float}> $points */
            $points = json_decode(file_get_contents(__DIR__ . '/extent-interior-points.json') ?: '{}', true, flags: JSON_THROW_ON_ERROR);
            self::$points = $points;
        }

        foreach ($extentCodes as $extentCode) {
            if (isset(self::$points[$extentCode])) {
                return [new Degree(self::$points[$extentCode][0]), new Degree(self::$points[$extentCode][1])];
            }
        }

        throw new RuntimeException('No precomputed interior point for ' . implode(', ', $extentCodes));
    }
}
